class StatusWidget(QWidget): """Widget displaying current state and status.""" def __init__(self, parent=None): super().__init__(parent) layout = QVBoxLayout(self) layout.setSpacing(8) # State indicator self.state_label = QLabel("State: STOPPED") self.state_label.setFont(QFont("Arial", 12, QFont.Bold)) self.state_label.setAlignment(Qt.AlignCenter) layout.addWidget(self.state_label) # Status details self.details_label = QLabel("Ready to start") self.details_label.setAlignment(Qt.AlignCenter) self.details_label.setWordWrap(True) layout.addWidget(self.details_label) # Hand info self.hand_info_label = QLabel("No hand detected") self.hand_info_label.setAlignment(Qt.AlignCenter) self.hand_info_label.setWordWrap(True) layout.addWidget(self.hand_info_label) layout.addStretch() def update_state(self, state: AirMouseState, details: str = ""): """Update state display.""" colors = { AirMouseState.STOPPED: "#888", AirMouseState.STARTING: "#ffaa00", AirMouseState.RUNNING: "#00aa00", AirMouseState.PAUSED: "#ffaa00", AirMouseState.ERROR: "#ff0000", } color = colors.get(state, "#888") self.state_label.setText(f"State: {state.value.upper()}") self.state_label.setStyleSheet(f"color: {color};") if details: self.details_label.setText(details) def update_hand_info(self, hand: Optional[object]): """Update hand information display.""" if hand and hasattr(hand, 'landmarks') and hand.landmarks: fingers = [] if hasattr(hand, 'finger_states'): for name, extended in hand.finger_states.items(): if extended: fingers.append(name.capitalize()) finger_str = ", ".join(fingers) if fingers else "None" self.hand_info_label.setText( f"Hand: {hand.handedness}
" f"Confidence: {hand.confidence:.2f}
" f"Extended: {finger_str}
" f"Pinch: {hand.is_pinch('thumb', 'index'):.3f}
" f"Fist: {hand.is_fist()}" ) else: self.hand_info_label.setText("No hand detected")

